/// <summary>
/// A <see cref = "AvailableCommandInput"/> variant this protocol version does not define.
/// </summary>
/// <remarks>
/// Holds the payload verbatim so it can be stored, replayed, or proxied unchanged.
/// ACP v2 requires that; failing to parse instead would lose the whole message.
/// </remarks>
public sealed class AvailableCommandInputUnknown : AvailableCommandInput
{
    /// <inheritdoc/>
    [JsonIgnore]
    public override string Discriminator => Kind;
    /// <summary>The discriminator value that was received.</summary>
    public required string Kind { get; init; }
    /// <summary>The payload exactly as it arrived.</summary>
    public required JsonElement Raw { get; init; }
}

/// <summary>Resolves <see cref = "AvailableCommandInput"/> by its <c>type</c> discriminator.</summary>
internal sealed class AvailableCommandInputConverter : JsonConverter<AvailableCommandInput>
{
    /// <inheritdoc/>
    public override AvailableCommandInput Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        using var document = JsonDocument.ParseValue(ref reader);
        var root = document.RootElement;
        var kind = root.TryGetProperty("type", out var marker) && marker.ValueKind == JsonValueKind.String ? marker.GetString() : null;
        return kind switch
        {
            "text" => new AvailableCommandInputText
            {
                Value = AcpJson.Read<TextCommandInput>(root, options)
            },
            _ => new AvailableCommandInputUnknown
            {
                Kind = kind ?? string.Empty,
                Raw = root.Clone()
            },
        };
    }

    /// <inheritdoc/>
    public override void Write(Utf8JsonWriter writer, AvailableCommandInput value, JsonSerializerOptions options)
    {
        if (value is AvailableCommandInputUnknown unknown)
        {
            unknown.Raw.WriteTo(writer);
            return;
        }

        writer.WriteStartObject();
        writer.WriteString("type", value.Discriminator);
        switch (value)
        {
            case AvailableCommandInputText typed:
                AcpJson.WriteMembers(writer, typed.Value, options);
                break;
            default:
                break;
        }

        writer.WriteEndObject();
    }
}

