/// <summary>Resolves <see cref = "DiffChange"/> by its <c>operation</c> discriminator.</summary>
internal sealed class DiffChangeConverter : JsonConverter<DiffChange>
{
    /// <inheritdoc/>
    public override DiffChange Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        using var document = JsonDocument.ParseValue(ref reader);
        var root = document.RootElement;
        var kind = root.TryGetProperty("operation", out var marker) && marker.ValueKind == JsonValueKind.String ? marker.GetString() : null;
        var fileType = AcpJson.ReadOptional<DiffFileType>(root, "fileType", options);
        var mimeType = AcpJson.ReadOptional<MediaType>(root, "mimeType", options);
        var meta = AcpJson.ReadOptional<System.Text.Json.JsonElement>(root, "_meta", options);
        return kind switch
        {
            "add" => new DiffChangeAdd
            {
                FileType = fileType,
                MimeType = mimeType,
                Meta = meta,
                Value = AcpJson.Read<DiffPathChange>(root, options)
            },
            "delete" => new DiffChangeDelete
            {
                FileType = fileType,
                MimeType = mimeType,
                Meta = meta,
                Value = AcpJson.Read<DiffPathChange>(root, options)
            },
            "modify" => new DiffChangeModify
            {
                FileType = fileType,
                MimeType = mimeType,
                Meta = meta,
                Value = AcpJson.Read<DiffPathChange>(root, options)
            },
            "move" => new DiffChangeMove
            {
                FileType = fileType,
                MimeType = mimeType,
                Meta = meta,
                Value = AcpJson.Read<DiffPathPairChange>(root, options)
            },
            "copy" => new DiffChangeCopy
            {
                FileType = fileType,
                MimeType = mimeType,
                Meta = meta,
                Value = AcpJson.Read<DiffPathPairChange>(root, options)
            },
            _ => new DiffChangeUnknown
            {
                FileType = fileType,
                MimeType = mimeType,
                Meta = meta,
                Kind = kind ?? string.Empty,
                Raw = root.Clone()
            },
        };
    }

    /// <inheritdoc/>
    public override void Write(Utf8JsonWriter writer, DiffChange value, JsonSerializerOptions options)
    {
        if (value is DiffChangeUnknown unknown)
        {
            unknown.Raw.WriteTo(writer);
            return;
        }

        writer.WriteStartObject();
        writer.WriteString("operation", value.Discriminator);
        if (value.FileType is { } fileTypeValue)
        {
            writer.WritePropertyName("fileType");
            JsonSerializer.Serialize(writer, fileTypeValue, options.GetTypeInfo(typeof(DiffFileType)));
        }

        if (value.MimeType is { } mimeTypeValue)
        {
            writer.WritePropertyName("mimeType");
            JsonSerializer.Serialize(writer, mimeTypeValue, options.GetTypeInfo(typeof(MediaType)));
        }

        if (value.Meta is { } metaValue)
        {
            writer.WritePropertyName("_meta");
            JsonSerializer.Serialize(writer, metaValue, options.GetTypeInfo(typeof(System.Text.Json.JsonElement)));
        }

        switch (value)
        {
            case DiffChangeAdd typed:
                AcpJson.WriteMembers(writer, typed.Value, options);
                break;
            case DiffChangeDelete typed:
                AcpJson.WriteMembers(writer, typed.Value, options);
                break;
            case DiffChangeModify typed:
                AcpJson.WriteMembers(writer, typed.Value, options);
                break;
            case DiffChangeMove typed:
                AcpJson.WriteMembers(writer, typed.Value, options);
                break;
            case DiffChangeCopy typed:
                AcpJson.WriteMembers(writer, typed.Value, options);
                break;
            default:
                break;
        }

        writer.WriteEndObject();
    }
}

