/// </remarks>
public sealed class ElicitationPropertySchemaUnknown : ElicitationPropertySchema
{
    /// <inheritdoc/>
    [JsonIgnore]
    public override string Discriminator => Kind;
    /// <summary>The discriminator value that was received.</summary>
