/// <summary>Resolves <see cref = "NesSuggestion"/> by its <c>kind</c> discriminator.</summary>
internal sealed class NesSuggestionConverter : JsonConverter<NesSuggestion>
{
    /// <inheritdoc/>
    public override NesSuggestion Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        using var document = JsonDocument.ParseValue(ref reader);
        var root = document.RootElement;
        var kind = root.TryGetProperty("kind", out var marker) && marker.ValueKind == JsonValueKind.String ? marker.GetString() : null;
        return kind switch
        {
            "edit" => new NesSuggestionEdit
            {
                Value = AcpJson.Read<NesEditSuggestion>(root, options)
            },
            "jump" => new NesSuggestionJump
            {
                Value = AcpJson.Read<NesJumpSuggestion>(root, options)
            },
            "rename" => new NesSuggestionRename
            {
                Value = AcpJson.Read<NesRenameSuggestion>(root, options)
            },
            "searchAndReplace" => new NesSuggestionSearchAndReplace
            {
                Value = AcpJson.Read<NesSearchAndReplaceSuggestion>(root, options)
            },
            _ => new NesSuggestionUnknown
            {
                Kind = kind ?? string.Empty,
                Raw = root.Clone()
            },
        };
    }

    /// <inheritdoc/>
    public override void Write(Utf8JsonWriter writer, NesSuggestion value, JsonSerializerOptions options)
    {
        if (value is NesSuggestionUnknown unknown)
        {
            unknown.Raw.WriteTo(writer);
            return;
        }

        writer.WriteStartObject();
        writer.WriteString("kind", value.Discriminator);
        switch (value)
        {
            case NesSuggestionEdit typed:
                AcpJson.WriteMembers(writer, typed.Value, options);
                break;
            case NesSuggestionJump typed:
                AcpJson.WriteMembers(writer, typed.Value, options);
                break;
            case NesSuggestionRename typed:
                AcpJson.WriteMembers(writer, typed.Value, options);
                break;
            case NesSuggestionSearchAndReplace typed:
                AcpJson.WriteMembers(writer, typed.Value, options);
                break;
            default:
                break;
        }

        writer.WriteEndObject();
    }
}

