                Value = AcpJson.Read<Content>(root, options)
            },
            "diff" => new ToolCallContentDiff
            {
                Value = AcpJson.Read<Diff>(root, options)
            },
            "terminal" => new ToolCallContentTerminal
            {
                Value = AcpJson.Read<Terminal>(root, options)
            },
